function errorResponse(error: HTTPError, config: H3Config, errHeaders?: Headers): Response {
  const { debug, problemDetails } = config;
  const baseHeaders = problemDetails ? problemHeaders : jsonHeaders;
  let headers: Headers = error.headers
    ? mergeHeaders(baseHeaders, error.headers)
    : new Headers(baseHeaders);
  if (errHeaders) {
    headers = mergeHeaders(headers, errHeaders);
  }
  const body = problemDetails
    ? problemDetailsBody(error, debug)
    : {
        ...error.toJSON(),
        stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
      };
  return new FastResponse(JSON.stringify(body, undefined, debug ? 2 : undefined), {
    status: error.status,
    statusText: error.statusText,
    headers,
  });
}

/**
 * RFC 9457 problem details body. Extension members come first so that a `body` or `data` key
 * can never override a standard member such as `status` or `type`.
 */
function problemDetailsBody(error: HTTPError, debug?: boolean): Record<string, unknown> {
  const unhandled = error.unhandled;
  return {
    ...(unhandled ? undefined : error.body),
    ...(unhandled ? undefined : { data: error.data }),
    ...(debug && error.stack ? { stack: error.stack.split("\n").map((l) => l.trim()) } : undefined),
    type: error.type ?? "about:blank",
    title: error.statusText,
    status: error.status,
    detail: unhandled ? "HTTPError" : error.message,
    instance: error.instance,
  };
}

