    return Promise.resolve()
      .then(() => onResponse(response as Response, event))
      .catch((error) => {
        if (!config.silent) console.error(error);
      })
      .then(
        () =>
          ((event as any)[kEventDispose] as DisposeState | undefined)?.observe(
            response as Response,
            val,
          ) ?? (response as Response),
      );
